function r2k(s){s=s.toLowerCase().trim().replace(/\s+/g,'').replace(/n['’]/g,'ん');let o='';while(s){if(/^([bcdfghjklmpqrstvwxyz])\1/.test(s)&&s[0]!=='n'){o+='っ';s=s.slice(1);continue}let m=0;for(let n=3;n>0;n--){const t=s.slice(0,n);if(RM[t]){o+=RM[t];s=s.slice(n);m=1;break}}if(m)continue;if(s==='nn'||(s[0]==='n'&&(s.length===1||!'aiueoyn'.includes(s[1])))){o+='ん';s=s.slice(s==='nn'?2:1);continue}if(s[0]==='n'&&s[1]==='n'){o+='ん';s=s.slice(1);continue}o+=s[0];s=s.slice(1)}return o.replace(/[ァ-ン]/g,c=>String.fromCharCode(c.charCodeAt(0)-96))}
