function dInit(){const c=document.getElementById('cv');if(!c)return;const x=c.getContext('2d');x.lineWidth=7;x.lineCap='round';x.lineJoin='round';x.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--ink').trim()||'#3d2433';let d=false;const q=e=>{const r=c.getBoundingClientRect();return[(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height]};V.dst=[];V.dchk=null;c.onpointerdown=e=>{if(V.dchk)return;d=true;const[a,b]=q(e);V.dst.push([[a,b]]);x.beginPath();x.moveTo(a,b);x.lineTo(a+.1,b);x.stroke();c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!d)return;const[a,b]=q(e);V.dst[V.dst.length-1].push([a,b]);x.lineTo(a,b);x.stroke()};c.onpointerup=c.onpointercancel=()=>{d=false}}
