function disR(r){const a=[...r],o=new Set();sh(a.map((c,i)=>MU[c]?i:-1).filter(i=>i>=0)).forEach(i=>{const b=a.slice();b[i]=MU[a[i]];o.add(b.join(''))});sh(ALLR.filter(x=>x!==r&&Math.abs([...x].length-a.length)<=1)).forEach(x=>o.add(x));o.delete(r);return[...o].slice(0,3)}
