const SLOT=(()=>{const n=K.length,pts=[];for(let i=0;i<n;i++){const r=Math.sqrt((i+.5)/n),t=i*2.399963;pts.push([100+62*r*Math.cos(t),78+40*r*Math.sin(t)])}let seed=7;const rnd=()=>(seed=(seed*16807)%2147483647)/2147483647,idx=[...pts.keys()];for(let i=n-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]]}return idx.map(i=>pts[i])})();
