function rec(k,ok,srs=true){const now=Date.now();S.pa[k]=now;S.miss[k]=ok?(S.miss[k]||0)-1:(S.miss[k]||0)+1;if(S.miss[k]<=0)delete S.miss[k];
// right answers move a card up only when it was due, so drilling the same day doesn't fake progress
if(srs){const c=S.cards[k];if(ok){if(!c)S.cards[k]={box:1,due:now+864e5};else if((c.due||0)<=now){c.box=Math.min(5,c.box+1);c.due=now+DAYS[c.box]*864e5}}else if(c){c.box=Math.max(0,c.box-1);c.due=now}}save()}
