rk:k=>KN?{k,kf:1,tag:'表記 · ¿Cuál es?',q:`<div class="rom">${k.es}</div><p>¿Cuál es en ${kat(k)?'katakana':'hiragana'}?</p>`,...opts(k.k,kdis(k).map(x=>x.k),df().o)}:null,
