function hit(k,ok){const p=V.ps;if(k)rec(k.k,ok);if(ok){p.sc++;p.cb++;ding(p.cb-1);p.best=Math.max(p.best,p.cb);addXP(p.cb>=3?6:5)}else{boop();p.cb=0;if(k)p.miss.push(k.k)}}
