// kana lessons: one row (about 5 kana) at a time, in the order people learn them
const LES=[];
if(KN){let ln=0;const add=(sec,cs,rule)=>{const ks=cs.map(c=>K.find(x=>x.k===c)).filter(Boolean);if(!ks.length)return;(rule||[]).forEach(r=>LES.push({id:'R'+r,sec,ks:[],rule:r,t:RU[r][0],r:RU[r][1].split('.')[0]+'.'}));LES.push({id:'L'+(ln++),sec,ks,t:ks.map(x=>x.k).join(' '),r:ks.map(x=>x.es).join(' ')})};
const ROWS=['あいうえお','かきくけこ','さしすせそ','たちつてと','なにぬねの','はひふへほ','まみむめも','やゆよ','らりるれろ','わをん'],DR=['がぎぐげご','ざじずぜぞ','だぢづでど','ばびぶべぼ','ぱぴぷぺぽ'],YR=['きしち','にひみ','りぎじ','びぴ'];
[0,1].forEach(kk=>{const cv=s=>kk?tw(s):s,nm=kk?'Katakana':'Hiragana';
ROWS.forEach((r,i)=>add(nm,[...cv(r)],kk&&!i?['kata']:!kk&&i===9?['wo']:null));
DR.forEach((r,i)=>add(nm+' con tenten',[...cv(r)],!i?(kk?null:['dak','tsu','long']):i===4&&!kk?['han']:null));
YR.forEach((r,i)=>add(nm+' combinados',[...cv(r)].flatMap(c=>['ゃ','ゅ','ょ'].map(s=>c+cv(s))),kk?null:i===0?['yoon']:null))});
const ex=K.filter(x=>x.g===10).map(x=>x.k);add('Katakana extendido',ex.slice(0,8),['ext']);add('Katakana extendido',ex.slice(8))}
const nextLesson=()=>LES.find(L=>!S.ls[L.id]);
function lessonItems(L){const known=K.filter(x=>kat(x)===kat(L.ks[0])&&(stOf(x.k)>=1||L.ks.includes(x)||S.ls[(LES.find(l=>l.ks.includes(x))||{}).id])),pool=known.length>=4?known:known.concat(K.filter(x=>x.g===L.ks[0].g&&!known.includes(x)));
// options only from kana you already know (plus this lesson's)
const mk=(k,t)=>{const o=sh(pool.filter(x=>x!==k&&snd(x)!==snd(k))),n=Math.min(4,o.length+1);if(t==='k2r')return{k,tag:'読み方 · ¿Cómo se lee?',q:`<div class="qk">${k.k}</div>`,...opts(k.es,o.map(x=>x.es),n)};if(t==='listen')return{k,kind:'listen',au:k.k,kf:1,tag:'聴解 · Escucha',q:`${sayB(k.k,30,1)}<p>¿Cuál escuchaste?</p>`,...opts(k.k,o.map(x=>x.k),n)};return{k,kf:1,tag:'表記 · ¿Cuál es?',q:`<div class="rom">${k.es}</div>`,...opts(k.k,o.map(x=>x.k),n)}};
return[...L.ks.map(k=>({kind:'intro',k})),...sh(L.ks.flatMap(k=>[mk(k,'k2r'),mk(k,hasJa()?'listen':'rk')])),...sh(L.ks.map(k=>mk(k,'rk')))]}
function runSession(m,items,lesson){V.tab='fc';V.rm=m;V.ps={m,items:items.filter(Boolean),i:0,sc:0,a:null,cb:0,best:0,miss:[],sel:[],lesson};render();window.scrollTo(0,0)}
