V.cm=0;
function calH(){const now=new Date(),m=new Date(now.getFullYear(),now.getMonth()+V.cm,1),y=m.getFullYear(),mo=m.getMonth(),last=new Date(y,mo+1,0).getDate(),lead=(m.getDay()+6)%7,today=iso(now);let cells='<span></span>'.repeat(lead),n=0;
for(let d=1;d<=last;d++){const k=iso(new Date(y,mo,d)),c=S.days[k]||0;if(c)n++;cells+=`<span class="cd ${c?'on':''} ${k===today?'td':''}" title="${c?c+(c===1?' respuesta':' respuestas'):''}">${d}</span>`}
return`<div class="box cal"><div class="ph"><b>Tu racha</b><span class="mut">${ic('flame',14,'#e07a4f','#ffe0cc')} ${S.streak} ${S.streak===1?'día':'días'} · récord ${Math.max(S.best||0,S.streak)}</span></div><div class="cnav"><button class="arrow ghost sm" onclick="V.cm--;render()" aria-label="Mes anterior">${ic('chL',18,'currentColor','none')}</button><b>${(t=>t[0].toUpperCase()+t.slice(1))(m.toLocaleDateString('es-CL',{month:'long',year:'numeric'}))}</b><button class="arrow ghost sm" ${V.cm>=0?'disabled':''} onclick="V.cm++;render()" aria-label="Mes siguiente">${ic('chR',18,'currentColor','none')}</button></div><div class="cgrid">${['L','M','X','J','V','S','D'].map(d=>`<i>${d}</i>`).join('')}${cells}</div><p class="mut" style="margin:10px 0 0;text-align:center">${n} ${n===1?'día estudiado':'días estudiados'} este mes</p></div>`}

// --- appearance: automatic (follows the system), light or dark; stored per device
