function themeColor(){const dark=document.documentElement.dataset.theme==='dark';const m=document.querySelector('meta[name=theme-color]');if(m)m.content=dark?'#1c1418':'#fff6f8'}
themeColor();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',themeColor);
