// which characters the games use: what you've seen (default) or rows of the table / concept groups you pick
S.gsel=S.gsel||[];V.gscr=0;
function gCustom(){if(!S.gsel.length)return[];if(KN){const ks=S.gsel.flatMap(r=>r.split(','));return K.filter(x=>ks.includes(x.k))}return K.filter(x=>S.gsel.includes(''+x.g))}
function gTog(key){S.gsel=S.gsel.includes(key)?S.gsel.filter(x=>x!==key):[...S.gsel,key];save();render()}
function gUse(c){if(!c){S.gsel=[];V.gpick=false;save()}else V.gpick=true;render()}
function gSelH(){const cs=gCustom(),cus=S.gsel.length>0,seenN=K.filter(x=>stOf(x.k)>=1).length;
const top=`<div class="gsel"><span class="mut">Jugar con:</span><button class="${!cus?'on':''}" aria-pressed="${!cus}" onclick="gUse(0)">Lo que ya viste <small>${seenN}</small></button><button class="${cus?'on':''}" aria-pressed="${cus}" onclick="gUse(1)">${cus?'Tu selección':'Elegir…'} ${cus?`<small>${cs.length}</small>`:''}</button></div>`;
if(!V.gpick)return top+(cus&&cs.length<6?'<p class="mut gwarn">Elige al menos 6 para usar tu selección; mientras tanto se juega con lo que ya viste.</p>':'');
const body=KN?`<div class="rscr">${['Hiragana','Katakana'].map((t,i)=>`<button class="${V.gscr===i?'on':''}" onclick="V.gscr=${i};render()">${t}</button>`).join('')}</div>${TROWS[V.gscr].map(([t,rows])=>`<div class="rgrp"><span class="mut">${t}</span><div class="rrows">${rows.map(r=>{const key=r.join(','),on=S.gsel.includes(key),seen=r.every(c=>stOf(c)>=1);return`<button class="${on?'on':''} ${seen?'':'new'}" aria-pressed="${on}" onclick="gTog('${key}')" lang="ja">${r.join('')}</button>`}).join('')}</div></div>`).join('')}`
:`<div class="rrows ggrp">${G.map((g,i)=>{const on=S.gsel.includes(''+i),l=K.filter(x=>x.g===i);return`<button class="${on?'on':''}" aria-pressed="${on}" onclick="gTog('${i}')"><b>${g[1]}</b><span lang="ja">${l.slice(0,6).map(x=>x.k).join('')}</span></button>`}).join('')}</div>`;
return top+`<div class="rpick gpick">${body}<p class="mut rsum">${cs.length} ${KN?'kana':'kanjis'} elegidos${cs.length<6?' · elige al menos 6':''} <button class="btn link" onclick="S.gsel=[];save();render()">Quitar todos</button> <button class="btn pri" onclick="V.gpick=false;render()">Listo</button></p></div>`}

// shared screens for the newer games: a ready screen and the end screen with the record
const gReady=(g,t,go)=>back()+`<div class="box gover"><div class="gglyph big" lang="ja">${g}</div><h2>¿Listo?</h2><p class="mut">${t}</p><button class="btn pri big" onclick="${go}">Empezar ${AR()}</button></div>`;
const gEnd=(g,big,sub,rec,again)=>back()+`<div class="box gover"><div class="gglyph big" lang="ja">${g}</div><h2>${big}</h2><p class="mut">${sub}</p>${rec}<p><button class="btn pri" onclick="gStart('${again}')">Otra vez</button> <button class="btn" onclick="gMenu()">Juegos</button></p></div>`;
function gRec(key,v,lower){const p=V.ps;if(p.saved)return;p.saved=1;if(v>0&&(!S.hs[key]||(lower?v<S.hs[key]:v>S.hs[key]))){S.hs[key]=v;p.rec=1;setTimeout(fanfare,250)}save()}
const recH=(key,txt)=>V.ps.rec?'<p class="grec">¡Nuevo récord!</p>':`<p class="mut">${txt(S.hs[key]||0)}</p>`;

// Atrapa: kana/kanji pop up in a 3×3 grid; tap only the one asked for
const WT=40;
function whackGo(){const p=V.ps;Object.assign(p,{ready:false,sc:0,cb:0,hits:0,miss:0,cells:Array(9).fill(null),t0:Date.now(),fx:{}});whackTarget();clearInterval(V.tm);V.tm=setInterval(whackTick,250);render()}
function whackTarget(){const p=V.ps,pool=V.gpool,old=p.tg;let k;do{k=pool[Math.random()*pool.length|0]}while(pool.length>1&&k===old);p.tg=k;p.th=0}
function whackTick(){const p=V.ps;if(!p||p.m!=='whack'||V.tab!=='games'||p.fin){clearInterval(V.tm);return}const now=Date.now(),life=[1700,1350,1050][S.dif];
if(now-p.t0>=WT*1000){p.fin=true;clearInterval(V.tm);gRec('whack',p.sc);render();return}
p.cells=p.cells.map(c=>c&&c.until>now?c:null);const empty=p.cells.map((c,j)=>c?-1:j).filter(j=>j>=0),hasT=p.cells.some(c=>c&&c.k===p.tg);
if(empty.length&&Math.random()<.55){const j=empty[Math.random()*empty.length|0],sim=x=>x===p.tg||(KN?snd(x)===snd(p.tg):gLab(x)===gLab(p.tg)),dec=V.gpool.filter(x=>!sim(x)),k=!hasT&&Math.random()<.6||!dec.length?p.tg:dec[Math.random()*dec.length|0];p.cells[j]={k,until:now+life*(.8+Math.random()*.5)}}
render()}
function whackHit(j){const p=V.ps;if(!p||p.m!=='whack'||p.fin||p.ready)return;const c=p.cells[j];if(!c)return;const ok=c.k===p.tg;p.cells[j]=null;p.fx={j,ok,t:Date.now()};
if(ok){p.cb++;p.hits++;p.sc+=10*(1+Math.floor(p.cb/5));ding(Math.min(p.cb-1,8));rec(c.k.k,true,false);if(++p.th>=4)whackTarget()}else{boop();p.cb=0;p.miss++;p.sc=Math.max(0,p.sc-5)}render()}
function whackV(){const p=V.ps;if(p.ready)return gReady('捕',`Arriba aparece lo que tienes que atrapar: ${KN?'un sonido, como «ka»':'un significado'}. Toca solo ${KN?'ese kana':'ese kanji'} cuando asome; los demás restan puntos. Cada 4 aciertos cambia el objetivo. Tienes ${WT} segundos.`,'whackGo()');
if(p.fin)return gEnd('捕',p.sc+' puntos',`${p.hits} atrapados · ${p.miss} errores · ${df().n}`,recH('whack',v=>'Récord: '+v+' pts'),'whack');
const left=Math.max(0,WT*1000-(Date.now()-p.t0)),fx=p.fx&&Date.now()-p.fx.t<350?p.fx:{},mult=1+Math.floor(p.cb/5);
return back()+`<div class="ghud"><span>${Math.ceil(left/1000)} s</span><span><b>${p.sc}</b> pts${mult>1?` <i class="gmult">×${mult}</i>`:''}</span></div><div class="wtg">Atrapa <b ${KN?'':'lang="es"'}>${KN?p.tg.es:gLab(p.tg)}</b></div><div class="wgrid">${p.cells.map((c,j)=>`<button class="whole ${c?'up':''} ${fx.j===j?(fx.ok?'hit':'bad'):''}" ${c?'':'tabindex="-1" aria-hidden="true"'} onpointerdown="event.preventDefault();whackHit(${j})" onclick="if(!event.detail)whackHit(${j})"><span lang="ja">${c?c.k.k:''}</span></button>`).join('')}</div>`}

// しりとり: chain words; the next one starts with the last kana of the previous one (readings in kana)
const toH=x=>[...x].map(c=>{const n=c.charCodeAt(0);return n>=0x30a1&&n<=0x30f6?String.fromCharCode(n-0x60):c}).join('');
const SMK={ぁ:'あ',ぃ:'い',ぅ:'う',ぇ:'え',ぉ:'お',ゃ:'や',ゅ:'ゆ',ょ:'よ',っ:'つ',ゎ:'わ'};
const shLast=w=>{const x=toH(w.kana).replace(/ー+$/,''),c=x[x.length-1];return SMK[c]||c},shFirst=w=>toH(w.kana)[0];
let SHW=null;const shWords=()=>SHW||(SHW=(()=>{const seen=new Set();return K.flatMap(k=>k.v.map(v=>({k,w:v.w,kana:KN?v.w:v.r,m:v.m}))).filter(x=>/^[ぁ-ゖァ-ヶー]+$/.test(x.kana)&&!seen.has(x.w)&&seen.add(x.w))})());
const shNext=(w,used)=>shWords().filter(x=>shFirst(x)===shLast(w)&&!used.has(x.w));
function shiriGo(){const p=V.ps,W=shWords(),start=sh(W.filter(w=>shLast(w)!=='ん'&&shNext(w,new Set([w.w])).length));Object.assign(p,{ready:false,lives:3,chain:0,best:0,used:new Set([start[0].w]),cur:start[0],a:null,hist:[]});shiriRound()}
function shiriRound(){const p=V.ps,W=shWords();let c=shNext(p.cur,p.used);
if(!c.length){const fresh=sh(W.filter(w=>!p.used.has(w.w)&&shLast(w)!=='ん'&&shNext(w,new Set([...p.used,w.w])).length));if(!fresh.length){p.fin=true;gRec('shiri',p.best);return render()}toast('No quedan palabras con «'+shLast(p.cur)+'»: empieza una nueva');p.cur=fresh[0];p.hist=[];p.used.add(p.cur.w);c=shNext(p.cur,p.used)}
const good=sh(c).sort((x,y)=>(shLast(x)==='ん')-(shLast(y)==='ん'))[0];if(!good){p.fin=true;gRec('shiri',p.best);return render()}const need=shLast(p.cur),wr=sh(W.filter(w=>shFirst(w)!==need&&w.w!==p.cur.w)).filter((w,i,a)=>a.findIndex(z=>shFirst(z)===shFirst(w))===i).slice(0,3);
p.o=sh([good,...wr]);p.c=p.o.indexOf(good);p.a=null;p.t0=Date.now();p.dur=[15000,10000,7000][S.dif];clearInterval(V.tm);V.tm=setInterval(shiriTick,200);render()}
function shiriTick(){const p=V.ps;if(!p||p.m!=='shiri'||V.tab!=='games'||p.fin||p.a!==null){clearInterval(V.tm);return}const left=p.dur-(Date.now()-p.t0),b=document.getElementById('shb');if(b)b.style.width=Math.max(0,left/p.dur*100)+'%';if(left<=0)shiriPick(-1)}
function shiriPick(j){const p=V.ps;if(p.a!==null||p.fin)return;clearInterval(V.tm);p.a=j;const ok=j===p.c,w=p.o[p.c];
if(ok){p.chain++;p.best=Math.max(p.best,p.chain);ding(Math.min(p.chain-1,8));rec(w.k.k,true,false);p.hist.push(w)}else{boop();p.lives--;p.chain=0;p.hist=[]}
render();clearTimeout(V.rt);V.rt=setTimeout(()=>{if(V.ps!==p)return;if(p.lives<=0){p.fin=true;gRec('shiri',p.best);return render()}p.cur=w;p.used.add(w.w);shiriRound()},ok?700:1800)}
const shRead=(w,hl)=>{const x=w.kana,i=x.replace(/ー+$/,'').length-1;return hl?`${x.slice(0,i)}<b class="shl">${x[i]}</b>${x.slice(i+1)}`:x};
function shiriV(){const p=V.ps;if(p.ready)return gReady('連',`しりとり es un juego de palabras japonés: cada palabra empieza con el último kana de la anterior (ねこ → こども → もも…). Elige la que sigue antes de que se acabe el tiempo. Tienes 3 vidas.`,'shiriGo()');
if(p.fin)return gEnd('連','Cadena de '+p.best,'Tu cadena más larga · '+df().n,recH('shiri',v=>'Récord: cadena de '+v),'shiri');
const hearts=[0,1,2].map(i=>ic('heart',22,i<p.lives?'#e8628e':'#d9c3cf',i<p.lives?'#fbd3df':'none')).join(''),cur=p.cur,d=p.a!==null;
return back()+`<div class="ghud"><span class="ghearts">${hearts}</span><span>Cadena <b>${p.chain}</b></span></div><div class="bar"><i id="shb" style="width:${d?0:100}%;transition:width .2s linear"></i></div>
<div class="box qcard shcur"><div class="shw" lang="ja">${KN?shRead(cur,1):cur.w}</div>${KN?'':`<div class="shr" lang="ja">${shRead(cur,1)}</div>`}<div class="mut">${cur.m}</div><p class="shq">¿Qué palabra empieza con <b lang="ja">${shLast(cur)}</b>?</p></div>
<div class="opts shop">${p.o.map((w,j)=>`<button class="opt ${d?(j===p.c?'ok':j===p.a?'bad':'dim'):''}" onclick="shiriPick(${j})" ${d?'disabled':''}><span lang="ja" class="shw2">${w.w}</span>${KN?'':`<small lang="ja">${d?w.kana:''}</small>`}${d?`<small>${w.m}</small>`:''}</button>`).join('')}</div>${p.hist.length>1?`<p class="shhist" lang="ja">${p.hist.slice(-6).map(w=>w.w).join(' → ')}</p>`:''}`}

// ¿Cuál no va?: three share something (concept group for kanji; row, vowel or script for kana), one doesn't
const OT=60,KROW=['あいうえお','かきくけこ','さしすせそ','たちつてと','なにぬねの','はひふへほ','まみむめも','やゆよ','らりるれろ','わを','がぎぐげご','ざじずぜぞ','だぢづでど','ばびぶべぼ','ぱぴぷぺぽ'];
// the first n items with a different value of f
const uniq=(a,f,n)=>{const seen=new Set();return a.filter(x=>!seen.has(f(x))&&seen.add(f(x))).slice(0,n)};
const kRow=k=>KROW.findIndex(r=>r.includes(toH(k.k))),kVow=k=>k.es.slice(-1);
function oddRound(){const p=V.ps;let three,odd,why;
if(KN){const B=K.filter(k=>k.k.length===1&&kRow(k)>=0&&k.k!=='ん'&&k.k!=='ン'),ty=sh(['row','row','vow','scr'])[0],sc=sh([0,1])[0],same=B.filter(k=>kat(k)===!!sc);
if(ty==='row'){const r=sh([...new Set(same.map(kRow))].filter(r=>same.filter(k=>kRow(k)===r).length>=3))[0];three=sh(same.filter(k=>kRow(k)===r)).slice(0,3);odd=sh(same.filter(k=>kRow(k)!==r))[0];const nm=x=>x===0?'las vocales':'la fila '+K.find(k=>toH(k.k)===KROW[x][0]).es.replace(/[aeiou]$/,'').toUpperCase();why=`${three.map(x=>x.k).join(' ')} son de ${nm(r)}; ${odd.k} es de ${nm(kRow(odd))}.`}
else if(ty==='vow'){const v=sh(['a','i','u','e','o'])[0];three=uniq(sh(same.filter(k=>kVow(k)===v)),kRow,3);odd=sh(same.filter(k=>kVow(k)!==v))[0];why=`${three.map(x=>x.k).join(' ')} terminan en «${v}»; ${odd.k} se lee «${odd.es}».`}
else{three=uniq(sh(same),snd,3);const snds=new Set(three.map(snd));odd=sh(B.filter(k=>kat(k)!==!!sc&&!snds.has(snd(k))))[0];why=`${three.map(x=>x.k).join(' ')} son ${sc?'katakana':'hiragana'}; ${odd.k} es ${sc?'hiragana':'katakana'}.`}}
else{const gs=sh([...new Set(K.map(k=>k.g))].filter(g=>K.filter(k=>k.g===g).length>=3)),g=gs[0],pref=V.gpool.filter(k=>k.g===g);three=sh(pref.length>=3?pref:K.filter(k=>k.g===g)).slice(0,3);const o2=V.gpool.filter(k=>k.g!==g);odd=sh(o2.length?o2:K.filter(k=>k.g!==g))[0];const gn=x=>G[x][1].replace(/<[^>]+>/g,'').trim();why=`${three.map(x=>x.k).join(' ')}: ${gn(g)}. ${odd.k} (${odd.es.split(',')[0]}): ${gn(odd.g)}.`}
p.o=sh([...three,odd]);p.c=p.o.indexOf(odd);p.why=why;p.a=null;render()}
function oddGo(){const p=V.ps;Object.assign(p,{ready:false,sc:0,err:0,t0:Date.now(),pen:0});oddRound();clearInterval(V.tm);V.tm=setInterval(()=>{const q=V.ps;if(!q||q.m!=='odd'||V.tab!=='games'||q.fin){clearInterval(V.tm);return}if(oddLeft()<=0){q.fin=true;clearInterval(V.tm);clearTimeout(V.rt);gRec('odd',q.sc);render()}else{const e=document.getElementById('odt');if(e)e.textContent=Math.ceil(oddLeft()/1000)+' s'}},250)}
const oddLeft=()=>OT*1000+0-(Date.now()-V.ps.t0)-V.ps.pen;
function oddPick(j){const p=V.ps;if(p.a!==null||p.fin)return;p.a=j;const ok=j===p.c;if(ok){p.sc++;ding(Math.min(p.sc-1,8));rec(p.o[p.c].k,true,false)}else{boop();p.err++;p.pen+=5000}render();clearTimeout(V.rt);V.rt=setTimeout(()=>{if(V.ps===p&&!p.fin)oddRound()},ok?900:2200)}
function oddV(){const p=V.ps;if(p.ready)return gReady('異',KN?'Tres kana comparten algo (la misma fila, la misma vocal o el mismo silabario) y uno no. Toca el intruso. Cada error te quita 5 segundos.':'Tres kanjis son del mismo grupo de significado y uno no. Toca el intruso. Cada error te quita 5 segundos.','oddGo()');
if(p.fin)return gEnd('異',p.sc+(p.sc===1?' acierto':' aciertos'),`${p.err} errores · ${df().n}`,recH('odd',v=>'Récord: '+v+' aciertos'),'odd');const d=p.a!==null;
return back()+`<div class="ghud"><span id="odt">${Math.ceil(Math.max(0,oddLeft())/1000)} s</span><span><b>${p.sc}</b> ${p.sc===1?'acierto':'aciertos'}</span></div><p class="mut" style="text-align:center;margin:4px 0 12px">¿Cuál no va con los demás?</p><div class="oddg">${p.o.map((k,j)=>`<button class="oddc ${d?(j===p.c?'ok':j===p.a?'bad':'dim'):''}" onclick="oddPick(${j})" ${d?'disabled':''}><span lang="ja">${k.k}</span>${d&&!KN?`<small>${k.es.split(',')[0]}</small>`:d?`<small>${k.es}</small>`:''}</button>`).join('')}</div>${d?`<div class="fbk ${p.a===p.c?'ok':'bad'}" style="margin-top:12px"><b>${p.a===p.c?'¡Exacto!':'Era '+p.o[p.c].k+' (−5 s)'}</b><p style="margin:4px 0 0" lang="ja">${p.why}</p></div>`:''}`}

// Sopa de letras: words from the vocabulary of the characters you play with, hidden in a grid
const SOPA=[{n:7,d:[[0,1],[1,0]]},{n:8,d:[[0,1],[1,0],[1,1]]},{n:9,d:[[0,1],[1,0],[1,1],[0,-1],[-1,0],[-1,-1],[1,-1],[-1,1]]}];
function sopaBuild(){const cf=SOPA[S.dif],N=cf.n,pool=V.gpool,seen=new Set();
const ws=sh(pool.flatMap(k=>k.v.map(v=>({k,w:v.w,r:v.r,m:v.m})))).filter(x=>{const L=[...x.w].length;if(L<2||L>N-1||seen.has(x.w))return false;seen.add(x.w);return KN?/^[ぁ-ゖァ-ヶー]+$/.test(x.w):true});
const g=Array.from({length:N},()=>Array(N).fill('')),placed=[];
for(const x of ws.sort((a,b)=>[...b.w].length-[...a.w].length)){if(placed.length>=6)break;const ch=[...x.w];let ok=null;
for(let t=0;t<200&&!ok;t++){const[dr,dc]=cf.d[Math.random()*cf.d.length|0],r0=Math.random()*N|0,c0=Math.random()*N|0,cells=ch.map((_,i)=>[r0+dr*i,c0+dc*i]);if(cells.every(([r,c],i)=>r>=0&&c>=0&&r<N&&c<N&&(!g[r][c]||g[r][c]===ch[i])))ok=cells}
if(ok){ok.forEach(([r,c],i)=>g[r][c]=ch[i]);placed.push({...x,cells:ok})}}
// fill the rest with characters of the same kind, so nothing gives the words away
const fill=KN?[...new Set(placed.flatMap(x=>[...x.w]).concat(pool.flatMap(k=>[...k.k])))].filter(c=>/[ぁ-ゖァ-ヶ]/.test(c)&&!/[ぁぃぅぇぉっゃゅょゎァィゥェォッャュョヮ]/.test(c)):[...new Set(pool.map(k=>k.k).concat(placed.flatMap(x=>[...x.w])))];
for(let r=0;r<N;r++)for(let c=0;c<N;c++)if(!g[r][c])g[r][c]=fill[Math.random()*fill.length|0];return{N,g,words:placed}}
function sopaGo(){const p=V.ps;let b;for(let i=0;i<8;i++){b=sopaBuild();if(b.words.length>=4)break}Object.assign(p,{ready:false,...b,found:[],sel:null,miss:0,t0:Date.now()});clearInterval(V.tm);V.tm=setInterval(()=>{const q=V.ps;if(!q||q.m!=='sopa'||V.tab!=='games'||q.fin){clearInterval(V.tm);return}const e=document.getElementById('sopat');if(e)e.textContent=Math.round((Date.now()-q.t0)/1000)+' s'},1000);render()}
function sopaTap(r,c){const p=V.ps;if(!p||p.m!=='sopa'||p.fin)return;if(!p.sel){p.sel=[r,c];return render()}
const[r0,c0]=p.sel;p.sel=null;const dr=Math.sign(r-r0),dc=Math.sign(c-c0),L=Math.max(Math.abs(r-r0),Math.abs(c-c0))+1;
if((r!==r0&&c!==c0&&Math.abs(r-r0)!==Math.abs(c-c0))||L<2){if(L>=2){boop();p.miss++}return render()}
const cells=Array.from({length:L},(_,i)=>[r0+dr*i,c0+dc*i]),key=cells.map(x=>x.join()).join(';'),w=p.words.find((x,i)=>!p.found.includes(i)&&(x.cells.map(y=>y.join()).join(';')===key||x.cells.slice().reverse().map(y=>y.join()).join(';')===key));
if(w){const i=p.words.indexOf(w);p.found.push(i);ding(p.found.length-1);rec(w.k.k,true,false);srSay('Encontraste '+w.w+': '+w.m);if(p.found.length===p.words.length){p.fin=true;clearInterval(V.tm);p.t=Math.max(1,Math.round((Date.now()-p.t0)/1000));gRec('sopa',p.t,true)}}else{boop();p.miss++}render()}
function sopaV(){const p=V.ps;if(p.ready)return gReady('探',`Hay palabras escondidas en la cuadrícula. Toca su primera letra y después la última para marcarla. ${['Las palabras van hacia la derecha o hacia abajo y ves cuál buscas.','También pueden ir en diagonal; ves su significado y su lectura.','Pueden ir en cualquier dirección, incluso al revés, y solo ves su significado.'][S.dif]}`,'sopaGo()');
if(p.fin)return gEnd('探',p.t+' segundos',`${p.words.length} palabras · ${p.miss} intentos fallidos · ${df().n}`,recH('sopa',v=>'Mejor tiempo: '+v+' s'),'sopa')+`<div class="box sopal">${p.words.map(w=>`<p><b lang="ja">${w.w}</b> <span class="mut" lang="ja">${KN?'':w.r} </span>· ${w.m}</p>`).join('')}</div>`;
const on=new Map();p.found.forEach(i=>p.words[i].cells.forEach(([r,c])=>on.set(r+','+c,i%5)));const sl=p.sel?p.sel.join(','):'';
return back()+`<div class="ghud"><span id="sopat">${Math.round((Date.now()-p.t0)/1000)} s</span><span><b>${p.found.length}</b> de ${p.words.length} palabras</span></div><div class="sopag" style="--n:${p.N}">${p.g.map((row,r)=>row.map((ch,c)=>{const k=r+','+c,f=on.has(k);return`<button class="sx ${f?'f f'+on.get(k):''} ${sl===k?'sel':''}" lang="ja" aria-label="${ch}, fila ${r+1}, columna ${c+1}" onclick="sopaTap(${r},${c})">${ch}</button>`}).join('')).join('')}</div><p class="mut sopah">${p.sel?'Ahora toca la última letra de la palabra.':'Toca la primera letra de una palabra.'}</p><div class="sopaw">${p.words.map((w,i)=>{const d=p.found.includes(i);return`<div class="${d?'d':''}">${d||S.dif===0?`<b lang="ja">${w.w}</b> `:''}<span>${S.dif===0&&!d?'':w.m}</span>${S.dif===1&&!d?` <span class="mut" lang="ja">(${KN?w.r:w.r})</span>`:''}${d&&!KN?` <span class="mut" lang="ja">${w.r}</span>`:''}</div>`}).join('')}</div>`}

// Lluvia: one kana/kanji falls at a time; answer before it lands
const gLab=k=>KN?k.es:S.dif===2?rdc(k):k.es.split(',')[0];
function gQ(k){const w=[...new Set(sh(V.gpool.filter(x=>x!==k&&(!KN||(kat(x)===kat(k)&&snd(x)!==snd(k))))).map(gLab))].filter(l=>l!==gLab(k));return w.length>=df().o-1?{k,...opts(gLab(k),w,df().o)}:QB.kmean(k)}
function rainNext(){const p=V.ps;clearTimeout(V.rt);if(p.fin)return;const pool=V.gpool,k=pool[Math.random()*pool.length|0],q=gQ(k);p.cur={...q,x:10+Math.random()*70,t0:Date.now(),id:++p.id};p.a=null;render();V.rt=setTimeout(()=>rainHit(-1),p.dur)}
function rainHit(j){const p=V.ps;if(!p||p.m!=='rain'||p.fin||p.a!==null)return;clearTimeout(V.rt);const it=p.cur,ok=j===it.c;p.a=j;rec(it.k.k,ok,false);
if(ok){p.cb++;p.ok++;const mult=1+Math.floor(p.cb/5);p.sc+=10*mult;ding(p.cb-1);if(p.ok%8===0){p.lv++;p.dur=Math.max(1700,Math.round(p.dur*.85));toast(icW('spark')+' ¡Nivel '+p.lv+'!')}}
else{boop();p.cb=0;p.lives--;if(p.lives<=0){p.fin=true;if(p.sc>(S.hs.rain||0)){S.hs.rain=p.sc;p.rec=1;setTimeout(fanfare,300)}save()}}
render();if(!p.fin)V.rt=setTimeout(rainNext,ok?380:1100)}
function rainGo(){V.ps.ready=false;rainNext()}
function rainV(){const p=V.ps;if(p.ready)return back()+`<div class="box gover"><div class="gglyph big">雨</div><h2>¿Listo?</h2><p class="mut">Van a caer ${KN?'kana':'kanjis'} que ya viste. Toca la respuesta correcta antes de que lleguen al suelo. Tienes 3 vidas, y cada 8 aciertos caen más rápido.</p><button class="btn pri big" onclick="rainGo()">Empezar ${AR()}</button></div>`;const it=p.cur,hearts=[0,1,2].map(i=>ic('heart',22,i<p.lives?'#e8628e':'#d9c3cf',i<p.lives?'#fbd3df':'none')).join('');
if(p.fin)return back()+`<div class="box gover"><div class="gglyph big">雨</div><h2>${p.sc} puntos</h2><p class="mut">Nivel ${p.lv} · ${p.ok} aciertos · ${df().n}</p>${p.rec?'<p class="grec">¡Nuevo récord!</p>':`<p class="mut">Récord: ${S.hs.rain||0} pts</p>`}<p><button class="btn pri" onclick="gStart('rain')">Otra vez</button> <button class="btn" onclick="gMenu()">Juegos</button></p></div>`;
const el=Date.now()-it.t0,d=p.a!==null,mult=1+Math.floor(p.cb/5);
return back()+`<div class="ghud"><span class="ghearts">${hearts}</span><span>Nivel ${p.lv}</span><span><b>${p.sc}</b> pts${mult>1?` <i class="gmult">×${mult}</i>`:''}</span></div><div class="rainbox"><div class="rdrop ${d?(p.a===it.c?'pop':'miss'):''}" style="left:${it.x}%;animation-duration:${p.dur}ms;animation-delay:-${d?0:el}ms;${d?'animation-play-state:paused;':''}"><b>${it.k.k}</b></div><div class="rground"></div></div><div class="qopts ${KN?'':''}">${it.o.map((o,j)=>`<button class="opt ${d?(j===it.c?'ok':p.a===j?'bad':''):''}" ${d?'disabled':''} onclick="rainHit(${j})">${o}</button>`).join('')}</div>`}

// Memoria: face-down pairs (kana ↔ reading, kanji ↔ meaning)
function memStart(){const n=[4,6,8][S.dif],ks=sh(V.gpool).slice(0,n),lab=k=>KN?k.es:S.dif===2?rdc(k):k.es.split(',')[0];V.rm='mem';V.ps={m:'mem',cards:sh(ks.flatMap((k,i)=>[{i,f:k.k,kf:1,k},{i,f:lab(k),k}])),open:[],done:[],moves:0,t0:Date.now(),fin:false};render()}
function memFlip(j){const p=V.ps;if(p.fin||p.open.length>=2||p.open.includes(j)||p.done.includes(p.cards[j].i))return;p.open.push(j);if(p.open.length===2){p.moves++;const[a,b]=p.open.map(x=>p.cards[x]);if(a.i===b.i){p.done.push(a.i);p.open=[];rec(a.k.k,true,false);ding(p.done.length-1);if(p.done.length*2===p.cards.length){p.fin=true;p.t=Math.round((Date.now()-p.t0)/1000);if(!S.hs.mem||p.t<S.hs.mem){S.hs.mem=p.t;p.rec=1;setTimeout(fanfare,300)}save()}}else{boop();setTimeout(()=>{p.open=[];render()},800)}}render()}
function memV(){const p=V.ps;if(p.fin)return back()+`<div class="box gover"><div class="gglyph big">記</div><h2>${p.t} segundos</h2><p class="mut">${p.moves} intentos · ${p.cards.length/2} parejas · ${df().n}</p>${p.rec?'<p class="grec">¡Nuevo récord!</p>':`<p class="mut">Mejor tiempo: ${S.hs.mem} s</p>`}<p><button class="btn pri" onclick="gStart('mem')">Otra vez</button> <button class="btn" onclick="gMenu()">Juegos</button></p></div>`;
return back()+`<div class="ghud"><span>${p.done.length} / ${p.cards.length/2} parejas</span><span>${p.moves} intentos</span></div><div class="memg c${p.cards.length>12?4:p.cards.length>8?4:4}">${p.cards.map((c,j)=>{const up=p.open.includes(j)||p.done.includes(c.i);return`<button class="mcard ${up?'up':''} ${p.done.includes(c.i)?'dn':''}" onclick="memFlip(${j})" aria-label="${up?c.f:'Carta boca abajo'}"><span class="mback">${logo(34)}</span><span class="mface ${c.kf?'kf':''}">${c.f}</span></button>`}).join('')}</div>`}
// leaving the games tab stops a running game
const _goG=go;go=function(t,b,g){clearTimeout(V.rt);if(t==='games')clearInterval(V.tm);V.gm=null;_goG(t,b,g)};

// keyboard access for clickable cards that aren't buttons
const _rka=render;render=function(){_rka();document.querySelectorAll('#app [onclick]:not(button):not(a):not(input):not(select), #mbox [onclick]:not(button)').forEach(e=>{if(!e.hasAttribute('tabindex'))e.tabIndex=0;e.setAttribute('role','button')})};
document.addEventListener('keydown',e=>{const t=e.target;if((e.key==='Enter'||e.key===' ')&&t.matches&&t.matches('[role=button][onclick]')){e.preventDefault();t.click()}});
const _ovGs=ovG;ovG=function(d){const i=V.oi;_ovGs(d);if(V.oi!==i)swish()};
