// --- automatic check of a drawing: each stroke against KanjiVG (how many, shape and place, direction, order)
// ヂ and ヅ aren't in KanjiVG as such: チ / ツ plus the two tenten strokes of ダ
['ヂチ','ヅツ'].forEach(([a,b])=>{if(!SV[a]&&SV[b]&&SV['ダ'])SV[a]=[...SV[b],...SV['ダ'].slice(-2)]});
const SMALLK={ゃ:'や',ゅ:'ゆ',ょ:'よ',ぁ:'あ',ぃ:'い',ぅ:'う',ぇ:'え',ぉ:'お',ャ:'ヤ',ュ:'ユ',ョ:'ヨ',ァ:'ア',ィ:'イ',ゥ:'ウ',ェ:'エ',ォ:'オ'};
let PSV=null;const RFC={};
// points along an SVG path (KanjiVG box is 109×109)
function samp(d,n=32){if(!PSV){const g=document.createElementNS('http://www.w3.org/2000/svg','svg');g.setAttribute('width','0');g.setAttribute('height','0');g.style.position='absolute';g.setAttribute('aria-hidden','true');PSV=document.createElementNS(g.namespaceURI,'path');g.appendChild(PSV);document.body.appendChild(g)}
PSV.setAttribute('d',d);const L=PSV.getTotalLength();return Array.from({length:n},(_,i)=>{const p=PSV.getPointAtLength(L*i/(n-1));return[p.x,p.y]})}
// reference strokes; combined kana (きゃ, ファ…) are built from the big kana plus the small one at the lower right
function refStrokes(k){if(k in RFC)return RFC[k];let r=null;try{if(SV[k])r=SV[k].map(d=>samp(d));else if(k.length===2&&SV[k[0]]&&SV[SMALLK[k[1]]])r=[...SV[k[0]].map(d=>samp(d).map(([x,y])=>[x*.66,y])),...SV[SMALLK[k[1]]].map(d=>samp(d).map(([x,y])=>[66+x*.42,50+y*.42]))]}catch(e){r=null}return RFC[k]=r}
const dNorm=st=>{const a=st.flat(),xs=a.map(p=>p[0]),ys=a.map(p=>p[1]),x0=Math.min(...xs),y0=Math.min(...ys),w=Math.max(...xs)-x0,h=Math.max(...ys)-y0,sz=Math.max(w,h)||1,cx=x0+w/2,cy=y0+h/2;return st.map(s=>s.map(([x,y])=>[(x-cx)/sz,(y-cy)/sz]))};
function dRes(pts,n=16){const d=[0];for(let i=1;i<pts.length;i++)d.push(d[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));const L=d[d.length-1];if(!L)return Array(n).fill(pts[0]);const out=[];let j=0;for(let i=0;i<n;i++){const t=L*i/(n-1);while(j<d.length-2&&d[j+1]<t)j++;const f=(t-d[j])/((d[j+1]-d[j])||1);out.push([pts[j][0]+(pts[j+1][0]-pts[j][0])*f,pts[j][1]+(pts[j+1][1]-pts[j][1])*f])}return out}
const dDist=(a,b)=>a.reduce((s,p,i)=>s+Math.hypot(p[0]-b[i][0],p[1]-b[i][1]),0)/a.length;
// result per stroke: ok, dir (backwards), order (it is another stroke), shape (doesn't match)
function dGrade(user,ref){const T=.17,U=dNorm(user).map(s=>dRes(s)),R=dNorm(ref).map(s=>dRes(s)),st=U.map((u,i)=>{const rv=u.slice().reverse();if(i<R.length){const a=dDist(u,R[i]),b=dDist(rv,R[i]);if(Math.min(a,b)<T)return b+.02<a?'dir':'ok'}return R.some((r,j)=>j!==i&&Math.min(dDist(u,r),dDist(rv,r))<T)?'order':'shape'});
const bad=st.filter(x=>x!=='ok').length,cnt=U.length-R.length;return{st,cnt,need:R.length,rate:bad+Math.abs(cnt)===0?2:bad+Math.abs(cnt)===1?1:0}}
function dCheck(){const p=V.ps,it=p.items[p.i],ref=refStrokes(it.k),c=document.getElementById('cv');if(!c||!ref)return;if(!V.dst.length)return toast('Dibuja primero el '+(KN?'kana':'kanji'));
const g=V.dchk=dGrade(V.dst,ref),x=c.getContext('2d'),col={ok:'#2fa36b',dir:'#e08a1e',order:'#d9455f',shape:'#d9455f'};x.clearRect(0,0,c.width,c.height);x.lineWidth=8;x.lineCap='round';x.lineJoin='round';
V.dst.forEach((s,i)=>{x.strokeStyle=col[g.st[i]];x.beginPath();s.forEach(([a,b],j)=>j?x.lineTo(a,b):x.moveTo(a,b));x.stroke();const[a,b]=s[0];x.fillStyle=col[g.st[i]];x.beginPath();x.arc(a,b,11,0,7);x.fill();x.fillStyle='#fff';x.font='bold 13px sans-serif';x.textAlign='center';x.textBaseline='middle';x.fillText(i+1,a,b)});
const msg=[];if(g.cnt<0)msg.push(`Te ${-g.cnt===1?'falta 1 trazo':'faltan '+(-g.cnt)+' trazos'}: son ${g.need}.`);if(g.cnt>0)msg.push(`Tienes ${g.cnt===1?'1 trazo':g.cnt+' trazos'} de más: son ${g.need}.`);
g.st.forEach((t,i)=>{if(t==='dir')msg.push(`El trazo ${i+1} va al revés: mira por dónde empieza.`);if(t==='order')msg.push(`El trazo ${i+1} está bien hecho, pero va en otro orden.`);if(t==='shape')msg.push(`El trazo ${i+1} no se parece al que corresponde.`)});
const ttl=g.rate===2?'¡Perfecto! Trazos, dirección y orden correctos':g.rate===1?'Casi: revisa un detalle':'Todavía no';if(g.rate===2)ding();else if(g.rate===0)boop();
document.querySelector('.dbtns').style.display='none';document.getElementById('dres').innerHTML=`<div class="fbk ${g.rate===2?'ok':g.rate===1?'mid':'bad'}"><b>${ttl}</b>${msg.length?`<ul class="dmsg">${msg.slice(0,4).map(m=>`<li>${m}</li>`).join('')}</ul>`:''}${g.rate===2?'':`<p class="mut" style="margin:6px 0 4px">El orden correcto:</p>${sv(it.k)}`}<p style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:10px 0 0"><button class="btn" onclick="dClr()">Intentar otra vez</button><button class="btn pri" onclick="dRate(${g.rate})">Siguiente ${AR()}</button></p></div>`;srSay(ttl)}
